// Task and its DAG edges (docs/design.md §Domain model and §Scheduler, ADR 0010).
// State, sub-state and iteration are not captured here: only the state machine moves them.
import { z } from "zod";
import { PrState, ResultKind, RiskLabel, SubState, TaskState } from "./enums.ts";

const unique = <T>(items: T[]): T[] => [...new Set(items)];

// Unsigned integer up to MAX_SAFE_INTEGER, like the column CHECK (ADR 0005).
export const Priority = z.int().min(0).max(Number.MAX_SAFE_INTEGER);

/** Short title generated by the refiner; shown in the UI and titles the PR. */
export const TASK_TITLE_MAX = 72;
export const TaskTitle = z.string().trim().min(1).max(TASK_TITLE_MAX);

/** Task number (#N): global sequential, immutable and never reused; does not replace the UUID (ADR 0015). */
export const TaskNumber = z.int().min(1).max(Number.MAX_SAFE_INTEGER);

/** How a task is identified to people: in herdr, notifications and the UI. */
export function taskLabel(number: number): string {
  return `#${number}`;
}

const Goal = z.string().trim().min(1).max(10_000);
const Tags = z.array(z.string().trim().min(1).max(64)).max(32).transform(unique);

export const TaskCreate = z.strictObject({
  projectId: z.uuid(),
  goal: Goal,
  tags: Tags.default(() => []),
  priority: Priority,
  // Task that originated this bugfix.
  causedBy: z.uuid().optional(),
  // Initial edges: the new task depends on these.
  dependsOn: z
    .array(z.uuid())
    .max(100)
    .transform(unique)
    .default(() => []),
});
export type TaskCreate = z.input<typeof TaskCreate>;

// PATCH: each present field replaces the stored one.
export const TaskUpdate = z.strictObject({
  goal: Goal.optional(),
  tags: Tags.optional(),
  priority: Priority.optional(),
});
export type TaskUpdate = z.input<typeof TaskUpdate>;

const Note = z.string().min(1).max(2000);

export const TaskCancel = z.strictObject({ note: Note.optional() });
export type TaskCancel = z.infer<typeof TaskCancel>;

export const Task = z.strictObject({
  id: z.uuid(),
  number: TaskNumber,
  projectId: z.uuid(),
  goal: z.string().min(1),
  // null until the first refinement; afterwards it does not change.
  title: TaskTitle.nullable(),
  tags: z.array(z.string()),
  priority: Priority,
  state: TaskState,
  subState: SubState.nullable(),
  // Cumulative number of reworks; it never decreases, not even when the task is resumed.
  verificationIteration: z.int().min(0),
  // Iteration at which the current verification cycle began; never above verificationIteration.
  verificationCycleStart: z.int().min(0),
  branch: z.string().nullable(),
  worktreePath: z.string().nullable(),
  prUrl: z.string().nullable(),
  prState: PrState.nullable(),
  riskLabel: RiskLabel.nullable(),
  // Result of a task completed without code (submit_result); null if it was delivered with a PR.
  resultKind: ResultKind.nullable(),
  result: z.string().nullable(),
  causedBy: z.uuid().nullable(),
  createdAt: z.date(),
  updatedAt: z.date(),
});
export type Task = z.infer<typeof Task>;

/** The other task of an edge, seen from a task: one of its dependencies or dependents. */
export const DependencyLink = z.strictObject({
  taskId: z.uuid(),
  number: TaskNumber,
  projectId: z.uuid(),
  goal: z.string(),
  title: TaskTitle.nullable(),
  state: TaskState,
  prState: PrState.nullable(),
  // Dependencies between projects are allowed, but the UI shows them as a risk.
  crossProject: z.boolean(),
  createdAt: z.date(),
});
export type DependencyLink = z.infer<typeof DependencyLink>;

export const TaskDependencies = z.strictObject({
  dependsOn: z.array(DependencyLink),
  dependents: z.array(DependencyLink),
});
export type TaskDependencies = z.infer<typeof TaskDependencies>;

export const TASK_CREATED = "task.created";
export const TASK_UPDATED = "task.updated";
export const TASK_TITLED = "task.titled";
export const TASK_DEPENDENCY_ADDED = "task.dependency_added";
export const TASK_DEPENDENCY_REMOVED = "task.dependency_removed";

export const TaskCreatedPayload = z.strictObject({
  // Optional: the task.created events before the number do not carry it.
  number: TaskNumber.optional(),
  projectId: z.uuid(),
  goal: z.string(),
  tags: z.array(z.string()),
  priority: Priority,
  causedBy: z.uuid().nullable(),
  dependsOn: z.array(z.strictObject({ dependsOnId: z.uuid(), crossProject: z.boolean() })),
});
export type TaskCreatedPayload = z.infer<typeof TaskCreatedPayload>;

const EditableFields = z.strictObject({
  goal: z.string().optional(),
  tags: z.array(z.string()).optional(),
  priority: Priority.optional(),
});

/** Only the fields that changed, with their previous value and the new one. */
export const TaskUpdatedPayload = z
  .strictObject({ from: EditableFields, to: EditableFields })
  .refine((p) => Object.keys(p.to).length > 0, "task.updated without changes");
export type TaskUpdatedPayload = z.infer<typeof TaskUpdatedPayload>;

/** The refiner set the task's title (only the first time). */
export const TaskTitledPayload = z.strictObject({ title: TaskTitle });
export type TaskTitledPayload = z.infer<typeof TaskTitledPayload>;

/** Payload of task.dependency_added and task.dependency_removed; the event goes on the dependent. */
export const TaskDependencyPayload = z.strictObject({
  dependsOnId: z.uuid(),
  crossProject: z.boolean(),
});
export type TaskDependencyPayload = z.infer<typeof TaskDependencyPayload>;

/** Filters of GET /api/tasks. */
export const TaskListQuery = z.strictObject({
  projectId: z.uuid().optional(),
  state: TaskState.optional(),
});
export type TaskListQuery = z.infer<typeof TaskListQuery>;
